select public.prepify_load_bank('Physics', 1, $j$[["If you are in chemistry lab which device help to calculate mass",["Stop watch","Calculator","Physical balance","Vernier caliper"],"C",5,1,"2a70d361ff7e",1],["The SI unit of luminous intensity is",["Newton","Kelvin","Kilogram","Candela"],"D",5,0,"b5e8205d0e0e",1],["What is the name of unit written as MW",["Milli watt","Mega watt","Million watt","Kilowatt"],"B",5,0,"3eebba22b906",1],["The upper jaws of vernier caliper is used to calculate",["Volume","Internal diameter","External diameter","Area"],"B",5,0,"cdb26f72bcb3",1],["The most precise device in vernier caliper and screw Gauge is",["Screw Gauge","Vernier caliper","Both","None"],"A",5,0,"809a51256de5",1],["The doubts present in our measurements is known as",["Precision","Accuracy","Errors","Significant digits"],"C",5,0,"3628a0d0c56d",1],["The least count for digital stop watch is",["1s","0.1s","0.01s","0.001s"],"C",5,0,"e89a99c7ba52",1],["Measuring cylinder is used to calculate",["Length","Volume","Area","Mass"],"B",5,0,"d8a1c70ea8a7",1],["If the car is crashed in west with 30m/s the quantity is",["Scalar","Base","Non physical","Vector"],"D",5,1,"9f48ed2f145a",1],["Which type of quantity momentum is",["Vector","Scalar","Base","Non physical"],"A",5,0,"5af6be11cb19",1],["Quantity that represent with letter and arrow head over it is",["Base","Derived","Scalar","Vector"],"D",5,0,"c7a5b11664a6",1],["The rule used to calculate the sum of vectors is",["Subtraction","Graphical analysis","Head to tail rule","Cramer's rule"],"C",5,0,"9d94488ee64c",1],["The frame of reference that describe the position of point or object",["Origin system","Coordinate system","SI system","None of these"],"B",5,0,"75be44190557",1],["A meter ruler has 100 cm divisions.Each centimeter is further subdivided into",["1 millimeters","10 millimeters","50 millimeters","100 millimeters"],"B",5,0,"2cf2f5fb27c6",1],["You have a page and beaker which device is used to calculate thickness",["Vernier caliper","Screw Gauge","Meter ruler","Measuring tape"],"B",5,1,"f33b3822a97e",1],["The prefix tera is equal to",["10¹²","10¹⁰","10¹⁵","10¹⁶"],"A",5,0,"53a2262672b4",1],["We use measuring cylinder to calculate volume. Which method is used in it?",["Head to tail","Displacement","Scalar","Significant digits"],"B",5,0,"5b924310cfb3",1],["Which type of error is removed by calibration of an instrument",["Random","Systematic","Personal","External"],"B",5,0,"63612ba6011a",1],["For scientific notation international accepted practice is that their should be how many digits before the decimal point",["Two","Three","Four","One"],"D",5,0,"3447578fffe4",1],["The term used internationally for multiples and submultiples of various units are known as",["Standard","Scientific notation","Prefixes","All of above"],"C",5,0,"50e62f2afb5c",1],["Separation between division on the vernier scale of vernier caliper is",["1cm","1mm","0.9mm","All of them"],"C",5,0,"2a0fdc298ab3",1],["Which type of error is often described as 'bias'",["Random","Systematic","Measurement","Human"],"B",5,0,"486a5f83d379",1],["Which quantity is largest?",["5 mm","5000 μm","0.005 m","All are equal"],"D",3,0,"c3e18b647b2e",1],["Which reading has four significant figures?",["0.0205","2.05","205","20.50"],"D",3,0,"bca1a6548740",1],["A digital vernier caliper has a least count of 0.01 mm. This means it can measure:",["Only whole millimetres","Up to 0.1 mm","Up to 0.01 mm","Up to 1 mm"],"C",3,0,"7e3593634563",1],["A measuring cylinder contains 40 cm³ of water. After a stone is fully immersed, the reading becomes 55 cm³. The volume of the stone is:",["15 cm³","40 cm³","55 cm³","95 cm³"],"A",3,1,"b167de7020d3",1],["A student measures the time for one oscillation of a pendulum. To reduce random error, he should:",["Measure one oscillation only.","Measure many oscillations and find the average.","Use a larger pendulum.","Use a ruler."],"B",3,1,"694a91744839",1],["A scale always shows 0.2 kg more than the true value. This is an example of:",["Random error","Systematic error","Human error","Percentage error"],"B",3,1,"65e5d63bbf7c",1],["How many base SI units are there?",["5","6","7","8"],"C",3,0,"85507b0ba132",1],["Round off 5.886 to two decimal places.",["5.87","5.89","5.80","5.90"],"B",3,0,"36a561420846",1],["A screw gauge is more precise than a vernier caliper because it has:",["greater size","more scales","smaller least count","longer spindle"],"C",3,0,"a0770e87795a",1],["A reading is written as 8.05 cm. Which digit is uncertain according to the idea of significant figures?",["8","5","0","All digits equally"],"B",3,0,"e6c623a91033",1],["Which instrument is most suitable for measuring the internal diameter of a hollow tube?",["Measuring tape","Meter rule","Vernier caliper","Stopwatch"],"C",3,0,"ed2a7f170076",1],["Which pair contains one scalar and one vector quantity?",["Speed and velocity","Force and weight","Distance and time","Mass and energy"],"A",3,0,"e4473686cd25",1],["The number 3.45 × 10⁷ contains:",["7 significant figures","3 significant figures","2 significant figures","45 significant figures"],"B",3,0,"f86564e3a80f",1],["A wire has a diameter of 2000 μm. Its diameter in millimetres is:",["0.2 mm","2 mm","20 mm","200 mm"],"B",3,0,"212356466f6e",1],["The value 5 × 10⁶ m can be written as:",["5 km","5 Mm","5 μm","5 nm"],"B",3,0,"b6080be9e37b",1],["The number 0.00072 is written in scientific notation as:",["7.2 × 10⁻⁵","7.2 × 10⁻⁴","72 × 10⁻⁵","0.72 × 10⁻³"],"B",3,0,"7213464ab3b6",1],["A student writes 56000 = 5.6 × 10⁻⁴. What is wrong?",["The coefficient is wrong.","The power of 10 should be positive.","Scientific notation cannot be used.","Nothing is wrong."],"B",3,1,"e35a41bab742",1],["Which of the following is a physical quantity?",["Honesty","Happiness","Intelligence","Length"],"D",3,0,"5a03e9031f5c",1],["A measurement without a unit is:",["Complete","Incomplete","Accurate","Precise"],"B",3,0,"e0d6ffd19939",1],["A quantity is measured in m/s. This quantity is most likely:",["Base quantity","Derived quantity","Non-physical quantity","Fundamental quantity"],"B",3,0,"607d1dde7e6f",1],["Which part of the measurement changes when the same length is expressed in cm instead of m?",["Unit only","Numerical magnitude only","Both magnitude and unit","Neither"],"C",3,0,"2f6802e6fbdd",1],["A measurement is meaningful only when:",["It has a large numerical value.","It has a unit.","It has a numerical magnitude and a unit.","It has direction."],"C",3,0,"5b3b58e01611",1],["In vector addition, the tail of the second vector is joined to the:",["Tail of first vector","Head of first vector","Midpoint of first vector","Origin"],"B",3,0,"07ffba4c57d3",1],["The length of a vector arrow represents its:",["direction","unit","magnitude","position"],"C",3,0,"6dad38c704a4",1],["Which one of the following has SI unit m²?",["area","volume","speed","density"],"A",3,0,"1f8b1a043032",1],["The least count of a measuring instrument tells us:",["its length","its maximum reading","the smallest measurement it can measure","its weight"],"C",3,0,"074ebf192d75",1],["Which instrument is most suitable for measuring the thickness of a sheet of paper?",["Measuring tape","Screw gauge","Vernier caliper","Stopwatch"],"B",3,0,"56ff49232b83",1],["A measurement taken with a vernier caliper is 6.24 cm. If the main scale reading is 6.2 cm, the coinciding vernier division is:",["2nd","4th","24th","6th"],"B",3,1,"411540de471e",1],["If the zero of the vernier scale is to the right of the zero of the main scale, the zero error is",["Positive","Negative","infinite","zero"],"A",3,0,"fc871e622035",1],["Which one of the following is NOT a derived unit?",["pascal","μm (micrometer)","joule","Newton"],"B",3,0,"198c063e0fa2",1],["Arrange the following SI prefixes in increasing order of magnitude: Pico, Nano, Milli, Micro",["Milli, Micro, Nano, Pico","Pico, Nano, Micro, Milli","Nano, Pico, Micro, Milli","Micro, Milli, Nano, Pico"],"B",3,0,"930bafc0e6b2",1],["What is the \"head-to-tail rule\" used for?",["Subtracting vectors","Multiplying vectors","Adding vectors","Finding the magnitude of a single vector"],"C",3,0,"44d115ed2575",1]]$j$::jsonb, false);
select public.prepify_load_bank('Physics', 2, $j$[["If there are three points on basketball P1,P2 and P3 moves parallel to each other and there is no change in orientation which type of motion is this",["Translatory","Rotatory","Vibratory","Random"],"A",5,1,"5cc82e9182fa",1],["Study of motion without discussing the cause of motion is called",["Kinematics","Dynamics","Heat","Motion"],"A",5,0,"ad46c67c0ed0",1],["The rest and motion of an object is explained by which property",["Absolute","Constant","Variable","Relative"],"D",5,0,"c2aed1d75b98",1],["When an object repeat its motion about a point again and again this motion is known as",["Translatory","Rotatory","Vibratory","None of these"],"C",5,0,"29c53d356815",1],["Which type of motion of earth causes day and night on earth",["Circular","Rotatory","Vibratory","Random"],"B",5,0,"939729193f06",1],["If an object is moving from point A to B and take turn moves toward C it's total path is explained by",["Distance","Displacement","Speed","Velocity"],"A",5,1,"baea97e6f2b5",1],["What is the name for this symbol '∆'",["Vector","Force","Delta","Rho"],"C",5,0,"14a0e823f0f9",1],["If Sir Jamal running in an Olympics and the running track is oval shape what is his displacement",["Maximum","Minimum","Zero","Equal"],"C",5,1,"cd1470d2c675",1],["If a car is moving with a velocity of 70Km/hr neither speeding up nor slowing down which type of velocity is this",["Variable","Instantaneous","Uniform","Average"],"C",5,1,"1c3b760c2048",1],["If the distance time graph represent a parallel line along time Axis what information we get from this",["Uniform motion","Rest","Acceleration","Speed"],"B",5,0,"f7a35986c94d",1],["If there is no a resistance a piece of paper and a coin is dropped from a top of building which would strike the earth first",["Paper","Coin","Dropper","Both at same time"],"D",5,1,"b6795e206d8c",1],["If this speed and direction of moving body does not change with time then it's velocity is said to be",["Uniform","Contact","Variable","Zero"],"A",5,0,"5abe3f4ede45",1],["If the direction of motion of a body and acceleration are in same direction then acceleration will be",["Uniform","Positive","Negative","Zero"],"B",5,0,"8fe93cf050ef",1],["If an object is dropped from top of building and is freely falling so the value of g depends on",["Mass","Speed","Size","Height"],"D",5,0,"a9417370c34a",1],["A person A sitting in a bus says that he is at rest but an observer B standing on a road says that A is moving the right person is",["Person B","Person A","Both person","None of these"],"C",5,1,"982ed9d955c6",1],["When an object is moving with uniform changing speed then the slope of speed time graph determine the magnitude of",["Displacement","Velocity","Acceleration","Momentum"],"C",5,0,"b08a656bf229",1],["If an object is slowing down the acceleration will be",["Positive","Negative","Zero","Constant"],"B",5,0,"e956605f6462",1],["At an amusement park, a ride swings back and forth but never leaves the same spot. What type of motion is this?",["Linear motion","Circular motion","Oscillatory motion","Random motion"],"C",5,1,"246cfac2dc12",1],["A drone flies straight from the warehouse to drop a package 2km north, no turns. What type of motion is this?",["Rectilinear motion","Projectile motion","Rotational motion","Periodic motion"],"A",5,1,"a6ca7012bfc6",1],["A batsman hits the ball and it follows a curved path before landing on the ground. What type of motion is this?",["Uniform motion","Circular motion","Projectile motion","Vibratory motion"],"C",5,1,"24c8c18a8b6a",1],["Which type of motion is exhibited by a freely falling body?",["Circular Motion","Linear Motion","Rotatory Motion","Vibrational Motion"],"B",3,0,"e60ca4d75776",1],["An athlete runs exactly one complete lap around a circular running track of radius R. What are the values of distance (s) and displacement (Δd) respectively?",["s = 0, Δd = 2πR","s = 2πR, Δd = 0","s = πR², Δd = 2R","s = 2R, Δd = 0"],"B",3,1,"464080c982ff",1],["If a commuter travels 10 km due North, then makes a sharp right turn and drives 10 km due East, what is the total distance covered and the net displacement?",["Distance = 20 km, Displacement = 20 km","Distance = 14.14 km, Displacement = 20 km","Distance = 20 km, Displacement = 14.14 km North-East","Distance = 0 km, Displacement = 10 km"],"C",3,1,"4488a73703a9",1],["A delivery truck travels along a winding track of length 1200 m in 60 seconds. The straight-line distance from its starting warehouse to its destination is 600 m. What is its average speed?",["10 m/s","20 m/s","30 m/s","5 m/s"],"B",3,1,"233843f8f4a5",1],["An object is moving with a constant velocity of +15 m/s along a straight runway. What is its acceleration?",["+15 m/s²","-15 m/s²","Zero","Dependent on the total time elapsed"],"C",3,0,"8e16f5a6a026",1],["A sports car accelerates uniformly from 10 m/s to 30 m/s over a time interval of 5 seconds. What is the precise rate of change of its velocity?",["8 m/s²","4 m/s²","6 m/s²","2 m/s²"],"B",3,1,"89851d5fe393",1],["When an object is dropped in a true vacuum environment near Earth’s surface, its downward acceleration is:",["Dependent on the object’s total surface area profile","Directly proportional to the mass of the object","Constant at approximately 9.8 m/s², regardless of mass values","Progressively decreasing as the object gains velocity"],"C",3,0,"6d132cd92ce6",1],["If a heavy iron ball and a light wooden ball are dropped simultaneously from the top of a tall tower in a vacuum chamber, which ball strikes the base first?",["The heavy iron ball hits significantly earlier","The light wooden ball hits significantly earlier","Both balls strike the base at the exact same instant","It depends heavily on which ball was released with more force"],"C",3,1,"710352835c8d",1],["An object is dropped from rest from the edge of a high cliff. Assuming g = 10 m/s² for calculation ease, what will be its downward speed after exactly 3 seconds of free fall?",["15 m/s","30 m/s","45 m/s","9.8 m/s"],"B",3,1,"54d154502459",1],["The study of motion without considering the forces involved is called:",["Dynamics","Statics","Kinematics","Thermodynamics"],"C",3,0,"70ddc1ed8e1b",1],["What is an example of rotatory motion?",["A car moving on a road","A wheel spinning about its axle","A ball falling from a height","A person walking"],"B",3,0,"0b7c093e2ed3",1],["If a car is traveling westward along a straight highway and applies its brakes to slow down, what are the directions of its velocity and acceleration vectors respectively?",["Velocity is West, Acceleration is West","Velocity is East, Acceleration is West","Velocity is West, Acceleration is East","Both vectors drop instantly to zero"],"C",3,1,"7a5f5ae8bc01",1],["Which of the following is the correct formula for speed?",["Speed = Time / Distance","Speed = Distance x Time","Speed = Distance / Time","Speed = Time x Acceleration"],"C",3,0,"9954b8e72338",1],["When does an object accelerate?",["Only when its speed increases","Only when its speed decreases","Only when its direction of motion changes","When there is a change in its speed, direction, or both"],"D",3,0,"cf856d7284b2",1],["If a car is traveling around a circular track at a constant speed of 50 km/h, is it accelerating?",["Yes, because its direction is constantly changing","No, because the speed is constant","No, because the velocity is constant","Yes, because the distance is increasing"],"A",3,1,"cc487bf738dc",1],["What is the SI unit of acceleration?",["m/s","m/s²","m/s³","kg/m³"],"B",3,0,"a9845a4ab5d3",1],["The area under a speed–time graph represents:",["Speed","Volume","Acceleration","Distance"],"D",3,0,"9cb3cbdc7823",1],["A particle starts from rest and achieves a velocity of 24 m/s in a span of 6 seconds along a linear track. What is its average acceleration?",["4 m/s²","144 m/s²","2 m/s²","0.25 m/s²"],"A",3,1,"e748cecc7f5f",1],["If a body covers equal distance in equal intervals of time, then the speed of the body is known as:",["Uniform","Variable","Non uniform","All of these"],"A",3,0,"9a37eab3cb2a",1],["If a satellite is moving in a circle with constant speed, its velocity will be:",["Uniform","Constant","Variable","All of these"],"C",3,0,"5060f9795193",1],["If the velocity of the body is decreasing then its acceleration will be:",["Positive","Negative","Zero","Uniform"],"B",3,0,"601c7fd40759",1],["If the velocity of the body is increasing then its acceleration will be:",["Positive","Negative","Zero","Non-uniform"],"A",3,0,"520842ade0c6",1],["If the velocity of a body is uniform then its acceleration will be:",["Positive","Negative","Zero","Doubled"],"C",3,0,"46ae50438941",1],["A passenger train traveling eastward along a straight track begins to slow down as it approaches a station. The direction of the train's acceleration is:",["Toward the East","Toward the West","Vertically downward","It has no direction because it is slowing down"],"B",3,1,"4510b4a8f258",1],["An airplane is flying toward the Southeast when the pilot throttles back the engines, causing the plane to slow down. The direction of the aircraft's acceleration is toward the:",["Southeast","Northwest","Southwest","Northeast"],"B",3,1,"33a7c6a5ada3",1],["A driver presses the gas pedal of a car moving along a straight highway, causing it to speed up in the forward direction. In this situation, the car's acceleration is:",["Negative","Positive","Zero","Non-uniform"],"B",3,1,"8a3bbe81feaf",1],["A speed-time graph features a straight line sloping downward toward the right. This represents:",["Uniform acceleration","Uniform deceleration","Non-uniform acceleration","Constant speed"],"B",3,0,"a294ddb3eb3c",1],["When a distance-time graph shows a curved line that bends gradually upward (getting steeper), the motion of the body can be described as:",["Uniform speed","Constant velocity","Non-uniform speed where the object is speeding up","Non-uniform speed where the object is slowing down"],"C",3,0,"32576a985761",1],["The slope (or gradient) of a distance-time graph directly represents which physical quantity?",["Displacement","Acceleration","Distance","Speed"],"D",3,0,"87b98fb9cdd1",1],["If the distance-time graph of a moving object is a perfectly flat, horizontal line parallel to the time axis, it indicates that:",["The object is moving with constant speed","The object is at complete rest","The object is moving with uniform acceleration","The object is returning back to its starting point"],"B",3,0,"1ff11d87b15f",1],["An object is thrown vertically straight upward into the air. At the highest point of its flight, the object’s velocity and acceleration are:",["Velocity is zero, and acceleration is zero","Velocity is zero, and acceleration is equal to acceleration due to gravity","Velocity is maximum, and acceleration is zero","Velocity is maximum, and acceleration is equal to acceleration due to gravity"],"B",3,0,"5a670fa7f80f",1],["The gradient (slope) of speed time curve gives magnitude of:",["Distance","Speed","Time","Acceleration"],"D",3,0,"d7d864e9d686",1],["The speedometer of a car shows:",["Average speed","Instantaneous speed","Uniform acceleration","Total distance"],"B",3,0,"5a9343081594",1],["The motion of a guitar string when plucked is an example of:",["Linear motion","Circular motion","Vibratory motion","Random motion"],"C",3,0,"539b644b96c2",1]]$j$::jsonb, false);
select public.prepify_load_bank('Physics', 3, $j$[["If two forces act along the same straight line but in opposite directions, the magnitude of their resultant is found by which operation?",["Addition","Subtraction","Multiplication","Division"],"B",5,0,"1cf11b4eabba",1],["When vectors act at a certain angle instead of being parallel, which method must be drawn to add them?",["Algebraic addition","Head-to-tail rule","Direct subtraction","Simple linear scale"],"B",5,0,"5fa0005fb782",1],["If an object is moving in a straight line at a completely constant speed, what is the net external force acting on it?",["Max force","Variable force","Zero force","Infinite force"],"C",5,0,"3b5c2e6396b2",1],["A passenger falls backward when a bus accelerates rapidly from rest. Which property explains this?",["Weight","Velocity","Friction","Inertia"],"D",5,1,"978886b84393",1],["If you want to change the state of rest or uniform motion of any object, what type of force is required?",["Balanced force","Unbalanced force","Internal force","Zero force"],"B",5,0,"45e3c4c7cfe4",1],["Which physical quantity is the direct, fundamental measure of a body's inertia?",["Weight","Speed","Mass","Volume"],"C",5,0,"a18b0e0cf49a",1],["A net, completely unbalanced external force acts continuously on a macroscopic object. Which inherent property of this moving object will always undergo a change?",["Velocity","Intrinsic mass","Structural inertia","Gravitational weight"],"A",5,0,"c8302f092997",1],["A player catches a fast baseball with rigid, locked arms and stationary hands instead of pulling them backward during the catch. Which physical variable increases dramatically because of this action?",["Average impact force","Total momentum change","Total net impulse","Total duration of impact"],"A",5,1,"1299f1b42622",1],["A massive block of ice rests on a completely frictionless frozen lake. A heavy stone is thrown horizontally at the block and sticks to it upon impact. Right after the collision, what happens to the total kinetic energy and the total linear momentum of the two-body system?",["Both stay constant","Momentum drops, energy stays","Momentum stays, energy drops","Both values drop"],"C",5,1,"0b204faf5bb7",1],["According to Newton's third law of motion, action and reaction forces always act on which bodies?",["The same body","Different bodies","Only heavy bodies","Only moving bodies"],"B",5,0,"edbff4006ee7",1],["When a person jumps out of a small boat onto a dock, the boat moves backward. The backward motion of the boat is called what?",["Action force","Inertia force","Reaction force","Gravitational force"],"C",5,1,"125861656242",1],["An exceptional marksman fires a heavy armor-piercing bullet from a standard rifle. The bullet accelerates inside the barrel in 0.005 seconds, while the rifle's recoil velocity is felt by the marksman's shoulder over the exact same time frame. Why does the marksman's body easily withstand the recoil?",["Rifle feels less force","Marksman's mass resists acceleration","Bullet loses its momentum","Barrel eliminates the reaction"],"B",5,1,"03a3795c18f0",1],["Why do action and reaction forces never cancel each other out during motion?",["They are unequal","They act simultaneously","They act on different objects","They act along different lines"],"C",5,0,"0feadd3eedb2",1],["When a heavy stone is dropped, the Earth pulls the stone down. What does the stone do to the Earth?",["Nothing","Pushes it away","Pulls it up equally","Pulls it up less"],"C",5,1,"c1d32004396e",1],["A large, massive astronaut floating completely at rest in deep space throws a small, light wrench away from himself. Immediately after the throw, how do the magnitudes of their linear momentums compare?",["Astronaut has more momentum","Wrench has more momentum","Both momentums are equal","Both momentums are zero"],"C",5,1,"1193dffc8df8",1],["During the firing of a bullet from a rifle, why does the heavy rifle recoil with a much smaller velocity than the bullet?",["It experiences less force","It has a larger mass","Its momentum is lost","Friction stops it completely"],"B",5,1,"ce5faa46ef2c",1],["If a gas-propelled rocket accelerates upward in the complete vacuum of outer space, what does it push against to move forward?",["Atmospheric nitrogen","Its own ejected exhaust gases","Planetary magnetic fields","Surrounding cosmic dust"],"B",5,1,"447fb6212189",1],["What does the mathematical area under a Force-versus-Time graph directly represent?",["Acceleration","Linear momentum","Structural inertia","Impulse"],"D",5,0,"0a3c96da4399",1],["If a system is strictly classified as an \"isolated system,\" what must be the value of the net external force acting on it?",["Maximum","Constant and positive","Exactly zero","Dynamically variable"],"C",5,0,"21e06356aa3c",1],["According to Newton's second law written in terms of momentum, the net force acting on an object equals what?",["Total momentum","Rate of change of momentum","Product of momentum and time","Initial momentum value"],"B",5,0,"e6a96b2be3d2",1],["When a cricketer pulls his hands backward while catching a fast-moving ball, which variable is he deliberately increasing?",["Applied net force","Total change in momentum","Time interval of impact","Velocity of the ball"],"C",5,1,"9f2805d9da72",1],["What physical quantity is defined as the product of an object's intrinsic mass and its linear velocity vector?",["Force","Impulse","Inertia","Momentum"],"D",5,0,"13b4e323c32e",1],["If a body's acceleration is observed to be exactly zero, what must be true about the forces acting on it?",["No forces exist","Net force is zero","Force is maximum","Only gravity acts"],"B",5,0,"49980edc90fc",1],["Newton's laws of motion fail to provide accurate descriptions for objects moving at which speeds?",["Very low speeds","Medium speeds","Near speed of light","Zero speed"],"C",5,0,"ea788b630767",1],["If an object is moved from Earth to the Moon, which of its properties remains completely constant?",["Weight","Mass","Gravity","Size"],"B",5,0,"1155f5c9ffbf",1],["What happens to the weight of an object if it is taken to a location where the gravitational field strength is zero?",["Remains same","Becomes zero","Doubled","Minimally decreases"],"B",5,0,"623d5f305c5c",1],["A heavy truck breaks down on a highway, and a small compact car pushes it from behind to a service station. While the car is successfully speeding up the truck, how does the force of the car on the truck compare to the force of the truck on the car?",["Car force is greater","Truck force is greater","Both forces are equal","Car force is zero"],"C",5,1,"aa5a7791baae",1],["A standard commercial elevator is moving downward toward the ground floor at a high, completely uniform, unchanging velocity. If a passenger stands on a digital weighing scale inside this elevator, what value will the display show?",["True weight","Zero weight","Double weight","Slightly lower weight"],"A",5,1,"a8a30b26eb38",1],["Two interacting bodies form an isolated system. During a complex, multi-stage collision between them, what can be scientifically concluded about their individual linear momentums?",["Both change","Both stay constant","Only the lighter changes","Both instantly become zero"],"A",5,0,"6431c40a2826",1],["A high-speed railway train traveling at a constant velocity passes through an intense, localized storm where heavy rain falls vertically downward. As water accumulates inside the open cargo containers of the moving train, what must the train engine do to maintain its constant speed without changing its path?",["Maintain constant force","Increase forward force","Reduce forward force","Cut off the power"],"B",5,1,"82e7b0ea1454",1],["A book is resting on a table. Which force prevents it from passing through the table?",["Frictional force","Tension force","Normal force","Magnetic force"],"C",3,1,"1f80dac52829",1],["A person pulls a bucket upward using a rope. The force transmitted through the rope is:",["Normal force","Elastic force","Tension force","Gravitational force"],"C",3,1,"0501a9bfa486",1],["A cricketer catches a fast-moving ball by moving his hands backward. This reduces:",["Momentum","Impulse","Force of impact","Mass"],"C",3,1,"693ea9f24604",1],["Two students push a box equally in opposite directions. The box remains at rest because:",["No force acts","Resultant force is zero","Friction is absent","Weight becomes zero"],"B",3,1,"987867e2d03b",1],["Which force is responsible for keeping planets in orbit around the Sun?",["Magnetic force","Electrostatic force","Gravitational force","Nuclear force"],"C",3,0,"a9dc101bbc98",1],["A parachute slows a falling skydiver mainly because of:",["Tension","Normal force","Air resistance","Magnetic force"],"C",3,1,"d64a5705d879",1],["When a person walks, the forward motion is possible because of:",["Gravitational force","Friction between foot and ground","Tension","Electrostatic force"],"B",3,1,"a8c8a4ccc2e2",1],["An astronaut's mass on the Moon compared with Earth is:",["Greater","Smaller","Same","Zero"],"C",3,0,"e5ac49feb4d7",1],["An astronaut's weight on the Moon is:",["Same as on Earth","Greater than on Earth","Less than on Earth","Zero"],"C",3,0,"d2ffc53ca529",1],["Which pair represents contact forces only?",["Friction and tension","Gravity and magnetism","Electrostatic and magnetic","Gravity and tension"],"A",3,0,"03b9851235ad",1],["A magnet attracts an iron nail without touching it. This demonstrates:",["Contact force","Elastic force","Non-contact force","Normal force"],"C",3,1,"d4a91d0e5513",1],["The strongest fundamental force is:",["Gravitational","Electromagnetic","Weak nuclear","Strong nuclear"],"D",3,0,"aee4d375e0f9",1],["Which force is weakest but has an infinite range?",["Strong nuclear","Weak nuclear","Gravitational","Frictional"],"C",3,0,"49de92ebf6bf",1],["A truck and a bicycle have the same speed. Which has greater momentum?",["Bicycle","Truck","Same","Cannot be determined"],"B",3,1,"dac836c8107a",1],["Doubling the mass of a moving object while keeping velocity constant will:",["Halve momentum","Double momentum","Triple momentum","Leave momentum unchanged"],"B",3,0,"b125afcfd9a8",1],["Why is it difficult to stop a loaded truck than an empty one moving at the same speed?",["Greater friction","Greater momentum","Smaller inertia","Less force"],"B",3,1,"00df196bbee4",1],["If Earth suddenly had twice its present gravitational field strength, a person's:",["Mass and weight would double.","Mass would double, weight unchanged.","Weight would double, mass unchanged.","Both remain unchanged."],"C",3,0,"7f291813f946",1],["A ball is thrown vertically upward. At the highest point:",["Velocity and acceleration are zero.","Velocity is zero but acceleration is not.","Acceleration is zero but velocity is not.","Momentum is maximum."],"B",3,0,"0be2f8522267",1],["Two objects have equal momentum. Object X has twice the mass of object Y. Therefore:",["X has twice the velocity of Y.","Y has twice the velocity of X.","Velocities are equal.","Insufficient information."],"B",3,0,"31e9a688d39d",1],["A satellite moves in a circular orbit at constant speed. Which statement is correct?",["Its acceleration is zero.","Net force is zero.","Velocity changes continuously.","Momentum remains constant."],"C",3,0,"33e57e7090b7",1],["A heavier object has greater inertia because it has:",["Greater weight","Greater mass","Greater volume","Greater density"],"B",3,0,"44b90993d1fc",1],["A swimmer pushes water backward and moves forward due to:",["Inertia","Conservation of energy","Newton's Third Law","Weight"],"C",3,1,"1a60e0ea36c8",1],["A force can change all EXCEPT:",["Speed","Direction","Shape","Mass"],"D",3,0,"67570ebff527",1],["If mass doubles and acceleration remains constant, force becomes:",["Half","Double","Four times","Same"],"B",3,0,"fcf172002527",1],["Which statement about action and reaction forces is correct?",["They act on the same object","They cancel each other","They act on different objects","One is larger"],"C",3,0,